INSERT INTO guides (file, title, category, blurb, related, media_id, sort) VALUES ('fish-compatibility-chart.jpg','Freshwater Fish Compatibility Chart','Aquatics','All 22 species groups you will find in a US pet shop, 231 checked pairings, the eight combinations people get wrong, and the six rules that matter more than the chart.','/blog/fish-compatibility-chart', 76, 7);
INSERT INTO posts (slug, title, description, keywords, category, hero_image, body_html, status, created_at, updated_at) VALUES ('fish-compatibility-chart','Freshwater Fish Compatibility Chart 2026 (22 Species + Printable)','Which fish can live together? A checked compatibility chart for 22 common pet shop species — bettas, tetras, cichlids, corydoras, shrimp, snails and more — plus tank sizes and the pairings to avoid.','fish compatibility chart, freshwater fish compatibility, what fish can live with betta, angelfish tank mates, community fish list, do cichlids go with tetras, shrimp safe fish, goldfish tank mates, aquarium stocking guide, tropical fish compatibility','Aquatics', '','<p>Almost every aquarium disaster starts the same way: someone stands in front of a wall of tanks, likes the look of six different fish, and buys them. A fortnight later the guppies have shredded fins, the shrimp have vanished, and the "algae eater" has grown to the size of a shoe.</p>
<p>Fish compatibility isn''t about which species look nice together. It''s about <strong>temperament, adult size, water temperature, swimming level, and whether one animal considers the other food.</strong> The chart below covers the 22 groups you''ll actually find in a US pet shop, and every pairing in it has been cross-checked so it never contradicts itself.</p>
<p>Print it, screenshot it, take it shopping. It''ll save you more money than any product on this site.</p>

<h2>📊 The Compatibility Chart</h2>
<p>Find your first species in the left column, then read across to the number of the species you''re considering. The numbers along the top match the numbered list on the left.</p>

<div class="compat-legend">
  <span><b class="y">✓</b> Generally fine</span>
  <span><b class="c">~</b> Only with care — read the notes</span>
  <span><b class="n">✗</b> Don''t mix</span>
  <span><b class="s">◆</b> Keep one only / same-species caution</span>
</div>
<p class="scroll-hint">↔ Scroll the chart sideways on a phone, or download the printable version below.</p>
<div class="table-wrap"><table class="compat"><thead><tr><th class="rn"></th><th class="rl">Species</th><th class="cx" title="Betta">1</th><th class="cx" title="Sm tetra/rasbora">2</th><th class="cx" title="Fin-nippers">3</th><th class="cx" title="Danios">4</th><th class="cx" title="Guppy/Endler">5</th><th class="cx" title="Platy/molly/sword">6</th><th class="cx" title="Corydoras">7</th><th class="cx" title="Bristlenose">8</th><th class="cx" title="Otocinclus">9</th><th class="cx" title="Kuhli loach">10</th><th class="cx" title="Clown/yoyo loach">11</th><th class="cx" title="Gouramis">12</th><th class="cx" title="Angelfish">13</th><th class="cx" title="Rams/apistos">14</th><th class="cx" title="African cichlids">15</th><th class="cx" title="Large cichlids">16</th><th class="cx" title="Goldfish">17</th><th class="cx" title="Cherry shrimp">18</th><th class="cx" title="Amano shrimp">19</th><th class="cx" title="Snails">20</th><th class="cx" title="Crabs">21</th><th class="cx" title="Crayfish">22</th></tr></thead><tbody><tr><th class="rn">1</th><th class="rl">Betta (male)</th><td class="m s">◆</td><td class="m c">~</td><td class="m n">✗</td><td class="m c">~</td><td class="m n">✗</td><td class="m c">~</td><td class="m y">✓</td><td class="m y">✓</td><td class="m y">✓</td><td class="m y">✓</td><td class="m y">✓</td><td class="m n">✗</td><td class="m n">✗</td><td class="m c">~</td><td class="m n">✗</td><td class="m n">✗</td><td class="m n">✗</td><td class="m c">~</td><td class="m c">~</td><td class="m y">✓</td><td class="m c">~</td><td class="m n">✗</td></tr><tr><th class="rn">2</th><th class="rl">Small tetras &amp; rasboras</th><td class="m c">~</td><td class="m y">✓</td><td class="m c">~</td><td class="m c">~</td><td class="m y">✓</td><td class="m y">✓</td><td class="m y">✓</td><td class="m y">✓</td><td class="m y">✓</td><td class="m y">✓</td><td class="m y">✓</td><td class="m y">✓</td><td class="m c">~</td><td class="m y">✓</td><td class="m n">✗</td><td class="m n">✗</t